module.exports = async (args) => {
  if (!args.variables) args.variables = {};
  if (!args.variables.user) args.variables.user = {};
  if (!args.variables.user.workflow_start_epoch) {
    args.variables.user.workflow_start_epoch = Date.now();
  }
  return {
    outputFileObj: args.inputFileObj,
    outputNumber: 1,
    variables: args.variables
  };
};

const fs = require("fs");
const path = require("path");
const { execFileSync, spawnSync } = require("child_process");
const http = require("http");
const https = require("https");

// ============================================================================
// Arc AV1 True Single-Pass Monolithic Engine (v2.1 - Zero-Drift Parity)
// Consolidates Stream Sanitization, Audio Pruning & Standardization, Subtitle
// Normalization (Text->SRT, Bitmap->Copy), Chapter Clamping, Arc AV1 QSV
// Transcode, 7-Tier Dual-Condition Size Guard, and Discord Notifications.
// ============================================================================

const formatDuration = (ms) => {
  if (!ms || ms < 0) return "0s";
  const totalSec = Math.max(1, Math.round(ms / 1000));
  const h = Math.floor(totalSec / 3600);
  const m = Math.floor((totalSec % 3600) / 60);
  const s = totalSec % 60;
  if (h > 0) return `${h}h ${m}m ${s}s`;
  if (m > 0) return `${m}m ${s}s`;
  return `${s}s`;
};

const formatSize = (mb) => {
  if (mb === undefined || mb === null || isNaN(mb) || mb <= 0) return "0 MB";
  const abs = Math.abs(mb);
  if (abs >= 1024) return (abs / 1024).toFixed(2) + " GB";
  return abs.toFixed(1) + " MB";
};

// Self-contained helpers embedded into the Tdarr custom function at build time.
const safeFs = require('fs');
const safePath = require('path');
const safeChild = require('child_process');

function safeFreeSpaceMB(dir) {
  try {
    const s = safeFs.statfsSync(dir, { bigint: true });
    const bytes = s.bavail * s.bsize;
    if (bytes < 0n) return null;
    return Number(bytes / (1024n * 1024n));
  } catch (_) {
    try {
      const out = safeChild.execFileSync('df', ['-Pk', dir], { encoding: 'utf8', timeout: 10000, stdio: ['ignore', 'pipe', 'pipe'] });
      const lines = out.trim().split(/\r?\n/);
      const parts = lines[lines.length - 1].trim().split(/\s+/);
      if (parts.length < 6 || !/^\d+$/.test(parts[3])) return null;
      return Math.floor(Number(parts[3]) / 1024);
    } catch (_) { return null; }
  }
}

function makeJobDir(parent) {
  return safeFs.mkdtempSync(safePath.join(parent, 'tdarr-av1-'));
}

function validateOutput(ffprobe, source, output, expected) {
  const probe = (file) => JSON.parse(safeChild.execFileSync(ffprobe,
    ['-v', 'error', '-show_format', '-show_streams', '-of', 'json', file],
    { encoding: 'utf8', maxBuffer: 16 * 1024 * 1024, timeout: 120000 }));
  const src = probe(source), dst = probe(output);
  const video = (dst.streams || []).filter(s => s.codec_type === 'video' && !s.disposition?.attached_pic && !s.disposition?.timed_thumbnails);
  if (video.length !== 1) throw new Error(`Output has ${video.length} video streams, expected 1`);
  if (expected.codec && video[0].codec_name !== expected.codec) throw new Error(`Output video codec ${video[0].codec_name} does not match ${expected.codec}`);
  for (const type of ['audio', 'subtitle']) {
    const actual = (dst.streams || []).filter(s => s.codec_type === type).length;
    if (actual !== expected[type]) throw new Error(`Output ${type} count ${actual} does not match expected ${expected[type]}`);
    const expectedCodecs = expected[type + 'Codecs'];
    if (expectedCodecs) {
      const actualCodecs = (dst.streams || []).filter(s => s.codec_type === type).map(s => s.codec_name);
      expectedCodecs.forEach((codec, i) => {
        if (codec && actualCodecs[i] !== codec) throw new Error(`Output ${type} codec ${actualCodecs[i]} at index ${i} does not match ${codec}`);
      });
    }
  }
  const a = Number(src.format?.duration), b = Number(dst.format?.duration);
  if (!(a > 0) || !(b > 0) || !Number.isFinite(a) || !Number.isFinite(b)) throw new Error('Source or output duration unavailable');
  const tolerance = Math.max(1, a * 0.005);
  if (Math.abs(a - b) > tolerance) throw new Error(`Output duration ${b}s differs from source ${a}s (tolerance ${tolerance.toFixed(2)}s)`);
  return { sourceDuration: a, outputDuration: b };
}



const getFreeSpaceMB = safeFreeSpaceMB;

const formatPipelineMode = (rawMode) => {
  if (!rawMode) return "Intel Arc GPU (Full Hardware)";
  const mode = rawMode.trim();
  if (mode.includes("Full QSV Hardware")) {
    if (mode.includes("HDR10")) return "Intel Arc GPU • HDR10";
    if (mode.includes("HLG")) return "Intel Arc GPU • HLG";
    return "Intel Arc GPU (Full Hardware)";
  }
  if (mode.includes("Hybrid")) {
    if (mode.includes("Fallback")) return "Hybrid Fallback (CPU Decode + GPU Encode)";
    if (mode.includes("CPU Decode")) return "Hybrid (CPU Decode + GPU Encode)";
    if (mode.includes("Downsample")) return "Hybrid (Color Conversion + GPU Encode)";
    return "Hybrid (CPU + GPU)";
  }
  if (mode.includes("Subtitle Normalization") || mode.includes("Seek Healing") || mode.includes("Compliant") || mode.includes("Remux")) {
    return "Fast Remux (Subtitles & Seek Repair)";
  }
  if (mode.includes("Bloat")) {
    return "Original Preserved (Bloat Protected)";
  }
  return mode;
};

const cleanFolder = (fullPath) => {
  if (!fullPath || fullPath === "Unknown file") return "Unknown folder";
  const parts = fullPath.split("/").filter(p => p && p !== "mnt" && p !== "media");
  if (parts.length <= 1) return "Root";
  parts.pop();
  const take = Math.min(parts.length, 3);
  return parts.slice(-take).join(" / ");
};

const buildOutputObj = (base, newPath, cleanName) => {
  const parsedNew = path.parse(newPath);
  const nameWithoutExt = cleanName || parsedNew.name.replace(/_(salvaged|healed|eac3|temp|singlepass)$/g, "");
  const obj = {
    ...base,
    _id: newPath,
    file: newPath,
    fileNameWithoutExtension: nameWithoutExt,
    container: parsedNew.ext.replace(".", "")
  };
  ["ffProbeData", "meta", "mediaInfo", "scannerReads"].forEach(k => delete obj[k]);
  try { obj.file_size = fs.statSync(newPath).size / (1024 * 1024); } catch (e) {}
  return obj;
};

const sendWebhookWithRetry = async (urlStr, payloadData, tag = "Discord Notifier", maxRetries = 3) => {
  if (!urlStr || urlStr.includes("***") || urlStr.includes("YOUR_WEBHOOK")) return;
  const url = new URL(urlStr);
  const lib = url.protocol === "https:" ? https : http;
  const postData = typeof payloadData === "string" ? payloadData : JSON.stringify(payloadData);

  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    const result = await new Promise((resolve) => {
      const req = lib.request({
        hostname: url.hostname,
        port: url.port || undefined,
        path: url.pathname + url.search,
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "User-Agent": "Tdarr-DiscordNotifier/1.0",
          "Content-Length": Buffer.byteLength(postData)
        }
      }, (res) => {
        let body = "";
        res.on("data", chunk => { body += chunk; });
        res.on("end", () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            console.log(`[${tag}] Sent successfully on attempt ${attempt} (HTTP ${res.statusCode})`);
            resolve({ ok: true, statusCode: res.statusCode });
          } else if (res.statusCode === 429) {
            let retryAfter = 2000;
            try {
              const parsed = JSON.parse(body);
              if (parsed.retry_after) retryAfter = Math.ceil(parsed.retry_after * 1000);
            } catch (_) {}
            console.warn(`[${tag}] Rate limited (HTTP 429) on attempt ${attempt}. Waiting ${retryAfter}ms`);
            resolve({ ok: false, retry: true, delay: retryAfter, statusCode: 429 });
          } else if (res.statusCode >= 500) {
            console.warn(`[${tag}] Discord gateway error (HTTP ${res.statusCode}) on attempt ${attempt}`);
            resolve({ ok: false, retry: true, delay: attempt * 2000, statusCode: res.statusCode });
          } else {
            console.error(`[${tag} Fatal Error] HTTP ${res.statusCode}: ${body}`);
            resolve({ ok: false, retry: false, statusCode: res.statusCode });
          }
        });
      });

      req.on("error", (err) => {
        console.warn(`[${tag}] Network error on attempt ${attempt}: ${err.message || err}`);
        resolve({ ok: false, retry: true, delay: attempt * 2000, error: err });
      });

      req.setTimeout(15000, () => {
        console.warn(`[${tag}] Socket timeout (15s) on attempt ${attempt}`);
        req.destroy();
        resolve({ ok: false, retry: true, delay: attempt * 2000, timeout: true });
      });

      req.write(postData);
      req.end();
    });

    if (result.ok || !result.retry || attempt === maxRetries) {
      if (!result.ok && attempt === maxRetries) {
        console.error(`[${tag}] Failed to deliver notification after ${maxRetries} attempts.`);
      }
      break;
    }

    const waitMs = result.delay || (attempt * 2000);
    await new Promise(r => setTimeout(r, waitMs));
  }
};

module.exports = async (args) => {
  if (!args.variables) args.variables = {};
  if (!args.variables.user) args.variables.user = {};
  delete args.variables.user.safety_temp_dir;
  delete args.variables.user.safety_temp_output;

  const log = (msg) => {
    console.log(msg);
    if (typeof args.jobLog === "function") {
      try { args.jobLog(msg); } catch (_) {}
    }
  };
  const ffmpegBin = args.ffmpegPath || "ffmpeg";
  const ffprobeBin = process.env.TDARR_FFPROBE_PATH || "ffprobe";
  const gpuDevice = process.env.TDARR_ARC_DEVICE || args.userVariables?.library?.arc_device || args.userVariables?.global?.arc_device || "/dev/dri/renderD129";

  const webhookUrl = process.env.TDARR_DISCORD_WEBHOOK || "";
  const startEpoch = args.variables.user.workflow_start_epoch || Date.now();
  args.variables.user.workflow_start_epoch = startEpoch;

  const inputPath = args.inputFileObj?._id || args.inputFileObj?.file;
  if (!inputPath || !fs.existsSync(inputPath)) {
    console.log(`[Arc AV1 Single-Pass] File not found or inaccessible: ${inputPath}`);
    return { outputFileObj: args.inputFileObj, outputNumber: 2, variables: args.variables };
  }

  const parsed = path.parse(inputPath);
  const ext = parsed.ext.toLowerCase();
  const container = (args.inputFileObj?.container || "").toLowerCase();
  const rawSizeMB = (args.originalLibraryFile?.file_size || args.inputFileObj?.file_size || (fs.statSync(inputPath).size / (1024 * 1024)));
  const origPath = args.originalLibraryFile?._id || inputPath || "Unknown file";
  const fileName = origPath.split("/").pop();
  const titleName = (args.originalLibraryFile?.fileNameWithoutExtension || fileName.replace(/\.[^/.]+$/, "") || fileName)
    .replace(/(_(salvaged|healed|eac3|temp|singlepass)|-TdarrCacheFile-[A-Za-z0-9_-]+)$/g, "");
  const folderDisplay = cleanFolder(origPath);

  // 1. ISO Disc Image Guard
  const isoExts = [".iso", ".img", ".mdf", ".bin", ".nrg"];
  if (container === "iso" || isoExts.includes(ext)) {
    console.log(`[ISO Guard] Disc image detected: ${inputPath}. Removing file and alerting.`);
    const totalDurationStr = formatDuration(Date.now() - startEpoch);
    const isoPayload = {
      embeds: [{
        title: `🗑️ ${titleName}`,
        description: [
          `📁 **Size Reclaimed:** \`${formatSize(rawSizeMB)}\``,
          `⏱️ **Duration:** ${totalDurationStr}`
        ].join("\n"),
        color: 10181046,
        footer: { text: "Tdarr AV1 Flow • ISO Auto-Remediation" },
        timestamp: new Date().toISOString()
      }]
    };
    // Rescan only after deletion succeeds, regardless of Discord delivery.
    try {
      const originalIso = args.originalLibraryFile?._id || inputPath;
      if (originalIso !== inputPath) throw new Error("ISO working path differs from original library path; refusing to delete an uncertain file");
      fs.unlinkSync(originalIso);
      log(`[ISO Guard] Deleted original disc image: ${originalIso}`);
    } catch (e) {
      log(`[ISO Guard] Deletion failed: ${e.message || e}`);
      return { outputFileObj: args.inputFileObj, outputNumber: 2, variables: args.variables };
    }
    try { await sendWebhookWithRetry(webhookUrl, isoPayload, "Discord ISO Deleted", 3); }
    catch (e) { log(`[ISO Guard] Discord notification failed: ${e.message || e}`); }
    return { outputFileObj: args.inputFileObj, outputNumber: 3, variables: args.variables };
  }

  // 2. Stream Probing
  let streams = args.inputFileObj?.ffProbeData?.streams;
  if (!streams || streams.length === 0) {
    try {
      const rawProbe = execFileSync("ffprobe", [
        "-v", "error", "-show_streams", "-show_format", "-print_format", "json", inputPath
      ], { encoding: "utf8" });
      const probed = JSON.parse(rawProbe);
      streams = probed?.streams || [];
      if (args.inputFileObj) args.inputFileObj.ffProbeData = probed;
    } catch (e) {
      streams = [];
    }
  }

  const badImageCodecs = ["mjpeg", "bmp", "png", "gif", "tiff", "otf", "ttf"];
  const videoStreams = streams.filter(s => {
    if (s.codec_type !== "video") return false;
    const c = (s.codec_name || "").toLowerCase();
    const isAttachedPic = s.disposition?.attached_pic === 1 || s.disposition?.timed_thumbnails === 1;
    return !badImageCodecs.includes(c) && !isAttachedPic;
  });
  const mainVideo = videoStreams[0];

  if (!mainVideo) {
    console.log(`[Arc AV1 Single-Pass] No valid video stream found in: ${inputPath}`);
    return { outputFileObj: args.inputFileObj, outputNumber: 2, variables: args.variables };
  }

  const vCodec = (mainVideo.codec_name || "").toLowerCase();
  const width = parseInt(mainVideo.width || 0, 10) || 1920;
  const height = parseInt(mainVideo.height || 0, 10) || 1080;
  const rawPixFmt = (mainVideo.pix_fmt || "yuv420p").toLowerCase();
  const pixFmt = rawPixFmt.split("(")[0].trim();

  // 3. Color & HDR / DoVi Profile (Checking ffprobe color_transfer, color_trc, and side_data_list)
  const colorTransfer = (mainVideo.color_transfer || mainVideo.color_trc || "").toLowerCase();
  const colorSpace = (mainVideo.color_space || mainVideo.colorspace || "").toLowerCase();
  const colorPrimaries = (mainVideo.color_primaries || "").toLowerCase();
  const isHlg = colorTransfer === "arib-std-b67";
  const isPq = colorTransfer === "smpte2084";
  const isBt2020 = colorSpace === "bt2020nc" || colorSpace === "bt2020c" || colorPrimaries === "bt2020";
  const isDovi = Array.isArray(mainVideo.side_data_list) && mainVideo.side_data_list.some(sd =>
    String(sd.side_data_type || "").toLowerCase().includes("dovi") || sd.dv_profile !== undefined
  );
  const isHdr = isHlg || isPq || isBt2020 || isDovi;

  // 4. Near-Lossless Lookahead ICQ Rate Control & Max AV1 Bitrate Calibration
  let quality = 19;
  let tierTargetKbps = 4500;
  let tierMaxKbps = 8000;
  let maxAv1Kbps = 8000;
  let resTierLabel = "1080p";
  const maxDim = Math.max(width, height);
  const minDim = Math.min(width, height);
  if (maxDim <= 1024 && minDim <= 576) {
    quality = 18;
    tierTargetKbps = 1200;
    tierMaxKbps = 2200;
    maxAv1Kbps = 2200;
    resTierLabel = "SD";
  } else if (maxDim <= 1280 && minDim <= 720) {
    quality = 19;
    tierTargetKbps = 2500;
    tierMaxKbps = 4500;
    maxAv1Kbps = 4500;
    resTierLabel = "720p";
  } else if (maxDim <= 1920 && minDim <= 1080) {
    quality = 19;
    tierTargetKbps = 4500;
    tierMaxKbps = 8000;
    maxAv1Kbps = 8000;
    resTierLabel = "1080p";
  } else if (isHdr) {
    quality = 18;
    tierTargetKbps = 18000;
    tierMaxKbps = 32000;
    maxAv1Kbps = 32000;
    resTierLabel = "4K UHD HDR";
  } else {
    quality = 19;
    tierTargetKbps = 12000;
    tierMaxKbps = 20000;
    maxAv1Kbps = 20000;
    resTierLabel = "4K UHD SDR";
  }

  // True Video/Container Duration Resolution & Oversized AV1 Detection
  const parseHmsToSec = (str) => {
    if (!str || typeof str !== "string") return 0;
    const m = str.trim().match(/^(\d+):(\d{1,2}):(\d{1,2}(?:\.\d+)?)/);
    if (!m) return 0;
    return parseInt(m[1], 10) * 3600 + parseInt(m[2], 10) * 60 + parseFloat(m[3]);
  };
  let videoDurationSec = parseFloat(mainVideo.duration || 0);
  if (!(videoDurationSec > 0) && mainVideo.tags) {
    const durTagKey = Object.keys(mainVideo.tags).find(k => k.toUpperCase() === "DURATION" || k.toUpperCase().startsWith("DURATION-"));
    if (durTagKey) {
      videoDurationSec = parseHmsToSec(mainVideo.tags[durTagKey]);
    }
  }
  if (!(videoDurationSec > 0) && Array.isArray(args.inputFileObj?.mediaInfo?.track)) {
    const miVid = args.inputFileObj.mediaInfo.track.find(t => (t["@type"] || "").toLowerCase() === "video");
    if (miVid && miVid.Duration) {
      videoDurationSec = parseFloat(miVid.Duration) || 0;
    }
  }
  const formatDurationSec = parseFloat(args.inputFileObj?.ffProbeData?.format?.duration || 0);
  const durationSec = (videoDurationSec > 1 && formatDurationSec > 1)
    ? Math.min(videoDurationSec, formatDurationSec)
    : (videoDurationSec > 1 ? videoDurationSec : formatDurationSec);

  const normalizeLang = (raw) => {
    const l = (raw || "und").toLowerCase().trim().split(/[-_]/)[0];
    if (["eng", "en"].includes(l)) return "eng";
    if (["jpn", "ja", "jp"].includes(l)) return "jpn";
    if (["zho", "chi", "zh", "cmn", "yue"].includes(l)) return "zho";
    if (["ita", "it"].includes(l)) return "ita";
    if (["spa", "es"].includes(l)) return "spa";
    return l || "und";
  };

  // Ghost & Duplicate Stream Pruner: Remove 0-second ghost tracks and duplicate MKV track entries before bitrate estimation & stream mapping
  const seenStreamSigs = new Set();
  streams = streams.filter(s => {
    if (s.codec_type !== "audio" && s.codec_type !== "subtitle") return true;
    const c = (s.codec_name || "").toLowerCase();
    const lang = normalizeLang(s.tags?.language || s.tags?.LANGUAGE || "und");
    const ch = s.codec_type === "audio" ? parseInt(s.channels || 0, 10) : 0;
    const rawTitle = String(s.tags?.title || s.tags?.TITLE || "").trim();
    const durKey = s.tags ? Object.keys(s.tags).find(k => k.toUpperCase() === "DURATION" || k.toUpperCase().startsWith("DURATION-")) : null;
    const durVal = durKey ? String(s.tags[durKey] || "").trim() : "";
    if (durationSec > 10 && durVal && /^0+:0+:0+(?:\.0+)?$/.test(durVal)) {
      log(`[Ghost Stream Pruner] Omitted 0-second ghost ${s.codec_type} stream 0:${s.index} (${c}, lang=${lang}, title='${rawTitle}')`);
      return false;
    }
    const numBytes = String(s.tags?.NUMBER_OF_BYTES || s.tags?.["NUMBER_OF_BYTES-eng"] || "").trim();
    const numFrames = String(s.tags?.NUMBER_OF_FRAMES || s.tags?.["NUMBER_OF_FRAMES-eng"] || "").trim();
    const bps = String(s.tags?.BPS || s.tags?.["BPS-eng"] || s.bit_rate || "").trim();
    const statsSig = (numBytes || numFrames || bps) ? `${numBytes}:${numFrames}:${bps}` : "";
    if (statsSig) {
      const sig = `${s.codec_type}|${c}|${lang}|${ch}|${rawTitle.toLowerCase()}|${statsSig}`;
      if (seenStreamSigs.has(sig)) {
        log(`[Ghost Stream Pruner] Omitted duplicate ghost ${s.codec_type} stream 0:${s.index} (${c}, lang=${lang}, title='${rawTitle}')`);
        return false;
      }
      seenStreamSigs.add(sig);
    }
    return true;
  });

  const formatTags = args.inputFileObj?.ffProbeData?.format?.tags || {};
  const encodedByKey = Object.keys(formatTags).find(k => k.toLowerCase() === "encoded_by");
  const isEncodedByUs = Boolean(encodedByKey && String(formatTags[encodedByKey]).includes("ArcAV1_QSV"));

  let estVideoBitrateKbps = 0;
  if (durationSec > 0 && rawSizeMB > 0) {
    const totalBitrateKbps = (rawSizeMB * 1024 * 1024 * 8) / (durationSec * 1000);
    let nonVideoKbps = 0;
    streams.forEach(s => {
      if (s.codec_type === "audio") {
        const explicitKbps = Math.round(parseInt(s.bit_rate || s.tags?.BPS || 0, 10) / 1000);
        if (explicitKbps > 0 && explicitKbps < 15000) {
          nonVideoKbps += explicitKbps;
        } else {
          const ch = parseInt(s.channels || 2, 10);
          const c = (s.codec_name || "").toLowerCase();
          const prof = (s.profile || "").toLowerCase();
          const isLossless = prof.includes("dts-hd") || c.startsWith("pcm_") || ["truehd", "flac", "alac", "mlp"].some(m => c.includes(m));
          nonVideoKbps += isLossless ? (ch > 2 ? 3000 : 1000) : (ch > 2 ? 640 : 192);
        }
      } else if (s.codec_type === "subtitle") {
        const sc = (s.codec_name || "").toLowerCase();
        if (sc.includes("pgs") || sc.includes("dvd")) nonVideoKbps += 50;
      }
    });
    estVideoBitrateKbps = Math.max(0, Math.round(totalBitrateKbps - nonVideoKbps));
  } else if (parseInt(mainVideo.bit_rate || 0, 10) > 0) {
    estVideoBitrateKbps = Math.round(parseInt(mainVideo.bit_rate, 10) / 1000);
  }

  // Quality-based encoding is used; no bitrate clamp is applied.
  const isOversizedAV1 = (vCodec === "av1") && !isEncodedByUs && (estVideoBitrateKbps > maxAv1Kbps);
  if (isOversizedAV1) {
    log(`[Oversized AV1 Detector] AV1 video bitrate (~${estVideoBitrateKbps} kbps) exceeds ${resTierLabel} ceiling (${maxAv1Kbps} kbps). Re-encoding via Intel Arc QSV AV1.`);
  }
  const isAlreadyAV1 = (vCodec === "av1") && !isOversizedAV1;

  // 10-bit & Hardware Compatibility Detection
  const is10Bit = pixFmt.includes("10") || mainVideo.bits_per_raw_sample === "10" || mainVideo.bits_per_raw_sample === 10;
  const isH26410bit = (vCodec === "h264" && is10Bit); // Intel Arc lacks H.264 Hi10P hardware decoder
  const isVC1 = (vCodec === "vc1" || vCodec === "wmv3"); // Intel Arc lacks VC-1 hardware decoder
  const isNon420Chroma = pixFmt.includes("444") || pixFmt.includes("422");
  const needsProactiveHybrid = isH26410bit || isVC1 || isNon420Chroma;

  const encoderSupportedPixFmts = [
    "nv12", "p010", "p010le", "yuv420p", "yuv420p8", "yuv420p9le",
    "yuv420p10le", "yuv420p12le", "yuv420p16le"
  ];
  const isEncoderCompatible = isAlreadyAV1 || encoderSupportedPixFmts.includes(pixFmt) || isNon420Chroma;

  if (!isEncoderCompatible) {
    console.log(`[Arc AV1 Single-Pass] Incompatible pixel format (${pixFmt}) for QSV hardware encode.`);
    const totalDurationStr = formatDuration(Date.now() - startEpoch);
    const incompPayload = {
      embeds: [{
        title: `⚠️ ${titleName}`,
        description: [
          `📁 **Size:** \`${formatSize(rawSizeMB)}\``,
          `⚠️ **Reason:** Unsupported pixel format (${pixFmt}) or codec (${vCodec}) for hardware QSV`,
          `⏱️ **Duration:** ${totalDurationStr}`
        ].join("\n"),
        color: 16776960,
        footer: { text: "Tdarr AV1 Flow • QSV Compatibility Filter" },
        timestamp: new Date().toISOString()
      }]
    };
    await sendWebhookWithRetry(webhookUrl, incompPayload, "Discord Incompatible", 3);
    return { outputFileObj: args.inputFileObj, outputNumber: 2, variables: args.variables };
  }

  if (!isAlreadyAV1) {
    try { fs.accessSync(gpuDevice, fs.constants.R_OK | fs.constants.W_OK); }
    catch (err) { log(`[Arc GPU] Device not accessible: ${gpuDevice}: ${err.message || err}`); return { outputFileObj: args.inputFileObj, outputNumber: 2, variables: args.variables }; }
  }

  let pipelineMode = "";
  if (isAlreadyAV1) {
    pipelineMode = "Library Reprocessing: Subtitle Normalization & Seek Healing";
  } else if (isNon420Chroma) {
    pipelineMode = `Hybrid (${pixFmt} -> 4:2:0 Downsample + Arc QSV AV1 Encode)`;
  } else if (needsProactiveHybrid) {
    pipelineMode = `Hybrid (CPU Decode [${vCodec}${is10Bit ? " 10-bit" : ""}] + Arc QSV AV1 Encode)`;
  } else if (is10Bit) {
    pipelineMode = "Full QSV Hardware (Native 10-bit GPU Decode + Pass-Through VPP + GPU AV1 Encode)";
  } else {
    pipelineMode = "Full QSV Hardware (8-bit to 10-bit VPP + GPU AV1 Encode)";
  }
  if (!isAlreadyAV1 && isHdr) {
    pipelineMode += isHlg ? " [HLG]" : " [HDR10]";
  }

  // 5. Audio Filtering & Language Priority (eng, jpn, zho, chi, ita, spa, und)
  const allowedAudioLangs = ["eng", "jpn", "zho", "ita", "spa", "und"];
  const badAudioCodecs = ["apple_apac", "apac"];
  const rawAudioStreams = streams.filter(s => {
    if (s.codec_type !== "audio") return false;
    const c = (s.codec_name || "").toLowerCase();
    const cid = (s.codec_tag_string || s.codec_id || "").toLowerCase();
    return !badAudioCodecs.includes(c) && !badAudioCodecs.includes(cid) && c !== "none";
  });

  let candidateAudio = rawAudioStreams.filter(s => {
    const lang = normalizeLang(s.tags?.language || s.tags?.LANGUAGE || "und");
    return allowedAudioLangs.includes(lang);
  });
  if (candidateAudio.length === 0) candidateAudio = rawAudioStreams;

  // Conditional Priority: If Japanese audio is present, prune Chinese audio tracks
  const hasJapanese = candidateAudio.some(s => normalizeLang(s.tags?.language || s.tags?.LANGUAGE || "") === "jpn");
  if (hasJapanese) {
    const nonZho = candidateAudio.filter(s => {
      const rawLang = (s.tags?.language || s.tags?.LANGUAGE || "").toLowerCase();
      if (normalizeLang(rawLang) === "zho") {
        console.log(`[Audio Filter] Japanese present; pruning Chinese stream 0:${s.index} (${rawLang})`);
        return false;
      }
      return true;
    });
    if (nonZho.length > 0) candidateAudio = nonZho;
  }

  // Redundant Legacy Core & Downmix Pruning per canonical language
  const prunedAudioIndices = new Set();
  const langAudioMap = {};
  candidateAudio.forEach(s => {
    const lang = normalizeLang(s.tags?.language || s.tags?.LANGUAGE || "und");
    if (!langAudioMap[lang]) langAudioMap[lang] = [];
    langAudioMap[lang].push(s);
  });

  Object.keys(langAudioMap).forEach(lang => {
    const tracks = langAudioMap[lang];
    const masterTrack = tracks.find(s => {
      const c = (s.codec_name || "").toLowerCase();
      const prof = (s.profile || "").toLowerCase();
      const ch = parseInt(s.channels || 0, 10);
      return (ch >= 6) && (ch > 6 || prof.includes("dts-hd") || c.startsWith("pcm_") || ["truehd", "dts-hd ma", "flac", "alac"].some(m => c.includes(m)));
    });
    const hasSurround = tracks.some(s => parseInt(s.channels || 0, 10) > 2);

    tracks.forEach(s => {
      const c = (s.codec_name || "").toLowerCase();
      const prof = (s.profile || "").toLowerCase();
      const ch = parseInt(s.channels || 0, 10);
      const title = (s.tags?.title || s.tags?.TITLE || "").toLowerCase();
      const isCommentary = s.disposition?.comment === 1 || title.includes("commentary") || title.includes("description");
      const isLossyCore = (c === "ac3") || (c === "dts" && !prof.includes("dts-hd"));

      // Omit redundant legacy core (e.g. AC3/DTS 5.1 alongside TrueHD/DTS-HD MA/FLAC/PCM master)
      if (masterTrack && s.index !== masterTrack.index && ch === 6 && isLossyCore && !isCommentary) {
        prunedAudioIndices.add(s.index);
        console.log(`[Audio Pruner] Omitted duplicate legacy core stream 0:${s.index} (${c} ${ch}ch) in favor of master stream 0:${masterTrack.index}`);
      }
      // Omit redundant AAC stereo downmix if surround exists
      if (hasSurround && tracks.length > 1 && ch <= 2 && c === "aac" && !isCommentary) {
        prunedAudioIndices.add(s.index);
        console.log(`[Audio Pruner] Omitted redundant AAC stereo downmix stream 0:${s.index} for language '${lang}'`);
      }
    });
  });

  const finalAudioStreams = candidateAudio.filter(s => !prunedAudioIndices.has(s.index));

  // 6. Subtitle Filtering & Safe Format Normalization (eng, ita, spa, und)
  const allowedSubLangs = ["eng", "ita", "spa", "und"];
  const toSrtCodecs = ["ass", "ssa", "eia_608", "c608", "cea-608", "cea-708", "mov_text", "tx3g", "webvtt", "vtt"];
  const toSrtCodecIDs = ["mov_text", "tx3g", "c608", "eia_608"];

  const finalSubStreams = streams.filter(s => {
    if (s.codec_type !== "subtitle") return false;
    const c = (s.codec_name || "").toLowerCase();
    const cid = (s.codec_tag_string || s.codec_id || "").toLowerCase();
    // Drop corrupt 'none' or unmuxable s_text/webvtt tracks
    if (!c || c === "none" || cid === "s_text/webvtt") {
      console.log(`[Subtitle Filter] Dropping un-muxable subtitle stream 0:${s.index} (codec: ${c || cid || "none"})`);
      return false;
    }
    const lang = normalizeLang(s.tags?.language || s.tags?.LANGUAGE || "und");
    return allowedSubLangs.includes(lang);
  });

  const cleanBase = (args.originalLibraryFile?.fileNameWithoutExtension || parsed.name)
    .replace(/(_(salvaged|healed|eac3|temp|singlepass)|-TdarrCacheFile-[A-Za-z0-9_-]+)$/g, "");

  // 6b. Transcode Cache Path Routing & Hard Free-Space Requirement Guard (Section 53)
  const SHM_THRESHOLD_MB = 15360; // 15 GB
  const isLargeFile = rawSizeMB > SHM_THRESHOLD_MB;
  const envMinFreeMB = parseInt(process.env.TDARR_MIN_FREE_SPACE_MB || args.variables?.user?.min_cache_free_mb || 0, 10);
  const minFloorMB = envMinFreeMB > 0 ? envMinFreeMB : 20480; // 20 GB hard floor for dedicated disk
  const requiredDiskMB = Math.max(minFloorMB, Math.round(rawSizeMB * 1.25));
  const requiredShmMB = Math.max(2048, Math.round(rawSizeMB * 1.25));

  let selectedDir = null;

  // 1. Opportunistic RAM Fast-Track (/dev/shm direct priority for media <= 15 GB)
  if (!isLargeFile && fs.existsSync("/dev/shm")) {
    const shmFreeMB = getFreeSpaceMB("/dev/shm");
    if (shmFreeMB !== null && shmFreeMB >= requiredShmMB) {
      selectedDir = (typeof args.workDir === "string" && args.workDir.startsWith("/dev/shm"))
        ? args.workDir
        : "/dev/shm";
      log(`[Cache Route Guard] File size ${(rawSizeMB / 1024).toFixed(2)} GB <= 15 GB and /dev/shm has ${shmFreeMB} MB free RAM (Required: ${requiredShmMB} MB). Elevating transcode directly to /dev/shm (RAM Fast-Track)!`);
    } else {
      log(`[Cache Route Guard] File size ${(rawSizeMB / 1024).toFixed(2)} GB <= 15 GB but /dev/shm free RAM (${shmFreeMB !== null ? shmFreeMB + " MB" : "unknown"}) is below required ${requiredShmMB} MB. Diverting to dedicated disk cache.`);
    }
  } else if (isLargeFile) {
    log(`[Cache Route Guard] File size ${(rawSizeMB / 1024).toFixed(2)} GB exceeds 15 GB RAM limit. /dev/shm is prohibited to prevent host OOM. Diverting to dedicated disk cache.`);
  }

  // 2. Dedicated Disk Cache Fallback (if not elevated to RAM)
  if (!selectedDir) {
    const dedicatedCandidates = [];
    if (process.env.TDARR_DEDICATED_CACHE && fs.existsSync(process.env.TDARR_DEDICATED_CACHE)) {
      dedicatedCandidates.push(process.env.TDARR_DEDICATED_CACHE);
    }
    if (args.variables?.user?.dedicated_cache_dir && fs.existsSync(args.variables?.user?.dedicated_cache_dir)) {
      dedicatedCandidates.push(args.variables.user.dedicated_cache_dir);
    }
    if (args.workDir && fs.existsSync(args.workDir) && !args.workDir.includes("/dev/shm") && !dedicatedCandidates.includes(args.workDir)) {
      dedicatedCandidates.push(args.workDir);
    }
    ["/transcode_cache", "/temp", "/mnt/cache", "/app/unmappedNodeCache"].forEach(p => {
      if (fs.existsSync(p) && !dedicatedCandidates.includes(p)) dedicatedCandidates.push(p);
    });

    let bestCandidate = null;
    let bestCandidateAvailMB = -1;

    for (const cand of dedicatedCandidates) {
      const freeMB = getFreeSpaceMB(cand);
      if (freeMB !== null) {
        if (freeMB > bestCandidateAvailMB) {
          bestCandidate = cand;
          bestCandidateAvailMB = freeMB;
        }
        if (freeMB >= requiredDiskMB) {
          selectedDir = cand;
          log(`[Cache Route Guard] Selected dedicated cache '${cand}' with ${freeMB} MB free (Required: ${requiredDiskMB} MB).`);
          break;
        }
      } else {
        log(`[Cache Route Guard] Cannot determine available space for ${cand}; refusing it.`);
      }
    }

    if (!selectedDir) {
      const errMsg = `[Cache Space Guard FATAL] Insufficient free space on all candidate cache paths for '${cleanBase}'. Required: ${(requiredDiskMB / 1024).toFixed(2)} GB. Best available: ${bestCandidate ? (bestCandidateAvailMB / 1024).toFixed(2) + " GB on " + bestCandidate : "none"}. Aborting transcode to prevent ENOSPC/disk corruption.`;
      console.error(errMsg);
      throw new Error("Insufficient transcode cache space: required " + requiredDiskMB + " MB, available " + bestCandidateAvailMB + " MB");
    }
  }

  // A per-job directory prevents collisions for identical basenames.
  const targetDir = makeJobDir(selectedDir);
  const outputPath = path.join(targetDir, `${cleanBase}.mkv`);
  args.variables.user.safety_temp_dir = targetDir;
  args.variables.user.safety_temp_output = outputPath;

  // 7. Chapter Boundary Guard (Seek Healing for out-of-bounds chapter end_time against video/container duration)
  let clampedMetaPath = null;
  let hasClampedChapters = false;
  try {
    const probeChaptersRaw = execFileSync("ffprobe", [
      "-v", "error", "-show_chapters", "-print_format", "json", inputPath
    ], { encoding: "utf8" });
    const chapData = JSON.parse(probeChaptersRaw);
    const chaps = chapData?.chapters || [];
    if (chaps.length > 0 && durationSec > 0) {
      const lastChap = chaps[chaps.length - 1];
      const lastEndSec = parseFloat(lastChap.end_time || 0);
      if (lastEndSec > durationSec + 0.1) {
        log(`[Chapter Boundary Guard] Last chapter end_time (${lastEndSec}s) exceeds video/container duration (${durationSec}s). Clamping chapter boundaries.`);
        const maxMs = Math.round(durationSec * 1000);
        const metaLines = [";FFMETADATA1"];
        chaps.forEach((c, idx) => {
          const startMs = Math.min(Math.round(parseFloat(c.start_time || 0) * 1000), maxMs);
          let endMs = Math.round(parseFloat(c.end_time || 0) * 1000);
          if (endMs > maxMs) {
            endMs = maxMs;
          }
          metaLines.push("[CHAPTER]", "TIMEBASE=1/1000", `START=${startMs}`, `END=${endMs}`);
          const title = c.tags?.title || `Chapter ${idx + 1}`;
          metaLines.push(`title=${title}`);
        });
        clampedMetaPath = path.join(targetDir, `${cleanBase}_chapters.txt`);
        fs.writeFileSync(clampedMetaPath, metaLines.join("\n"));
        hasClampedChapters = true;
      }
    }
  } catch (chapErr) {
    // Non-fatal if chapter probe fails
  }

  // Helper to append audio & subtitle mappings to any FFmpeg command array
  const langDisplayMap = {
    eng: "English",
    jpn: "Japanese",
    zho: "Chinese",
    ita: "Italian",
    spa: "Spanish",
    und: "Audio"
  };
  const codecDisplayMap = {
    opus: "Opus",
    eac3: "E-AC-3",
    ac3: "AC3",
    dts: "DTS",
    aac: "AAC",
    flac: "FLAC",
    truehd: "TrueHD",
    alac: "ALAC",
    mp3: "MP3",
    vorbis: "Vorbis"
  };

  const appendAudioAndSubArgs = (cmdArgs) => {
    if (finalAudioStreams.length > 0) {
      finalAudioStreams.forEach((s, idx) => {
        cmdArgs.push("-map", `0:${s.index}`);
        const ch = parseInt(s.channels || 0, 10);
        const c = (s.codec_name || "").toLowerCase();
        const prof = (s.profile || "").toLowerCase();
        const isTranscodedToEac3 = ch > 2 && (c !== "eac3" || ch > 6);
        let actualCodec = "Audio";
        let finalCh = ch || 2;

        // Convert surround (>2ch) to E-AC3 5.1 @ 640k unless it is already E-AC3 <=6ch
        if (isTranscodedToEac3) {
          cmdArgs.push(`-c:a:${idx}`, "eac3", `-b:a:${idx}`, "640k");
          if (ch > 6) cmdArgs.push(`-ac:a:${idx}`, "6");
          actualCodec = "E-AC-3";
          finalCh = 6;
        } else {
          cmdArgs.push(`-c:a:${idx}`, "copy");
          if (c === "dts" && prof.includes("dts-hd")) {
            actualCodec = "DTS-HD MA";
          } else {
            actualCodec = codecDisplayMap[c] || (c ? c.toUpperCase() : "Audio");
          }
        }

        // Dynamic Audio Title Normalization & Codec Tag Sanitization
        const chLayout = finalCh === 6 ? "5.1" : (finalCh === 8 ? "7.1" : (finalCh === 1 ? "Mono" : "2.0"));
        const canonLang = normalizeLang(s.tags?.language || s.tags?.LANGUAGE || "und");
        const langName = langDisplayMap[canonLang] || (canonLang ? canonLang.toUpperCase() : "Audio");
        const rawTitle = String(s.tags?.title || s.tags?.TITLE || "");
        const strippedTitle = rawTitle
          .replace(/\[[^\]]*\]|\([^)]*\)/g, " ")
          .replace(/\b(x264|x265|h264|h265|hevc|av1|10b|10bit|8bit|\d+\s*kbps)\b/gi, " ")
          .replace(/\s+/g, " ")
          .trim();
        const isGenericOrEmpty = !strippedTitle || /^(english|eng|japanese|jap|jpn|chinese|zho|chi|mandarin|cantonese|italian|ita|spanish|spa|undetermined|und|stereo|surround|mono|audio|default|main|original|track\s*\d+|\d+\.\d+|aac|ac-?3|e-?ac-?3|ddp?|opus|dts(?:-hd)?(?:\s*ma)?|truehd|flac|pcm|\s|-|\/|:)+$/i.test(strippedTitle);
        const correctedTitle = isGenericOrEmpty
          ? `${langName} [${actualCodec} ${chLayout}]`
          : `${strippedTitle} [${actualCodec} ${chLayout}]`;
        cmdArgs.push(`-metadata:s:a:${idx}`, `title=${correctedTitle}`);
      });

      // Enforce Surround = default and Stereo = non-default (0) when both exist
      const hasSurround = finalAudioStreams.some(s => parseInt(s.channels || 0, 10) > 2);
      const hasStereo = finalAudioStreams.some(s => {
        const ch = parseInt(s.channels || 0, 10);
        return ch > 0 && ch <= 2;
      });
      if (hasSurround && hasStereo) {
        let defaultSet = false;
        finalAudioStreams.forEach((s, idx) => {
          if (parseInt(s.channels || 0, 10) > 2 && !defaultSet) {
            cmdArgs.push(`-disposition:a:${idx}`, "default");
            defaultSet = true;
          } else {
            cmdArgs.push(`-disposition:a:${idx}`, "0");
          }
        });
      }
    } else {
      cmdArgs.push("-an");
    }

    if (finalSubStreams.length > 0) {
      finalSubStreams.forEach((s, idx) => {
        const c = (s.codec_name || "").toLowerCase();
        const cid = (s.codec_tag_string || s.codec_id || "").toLowerCase();
        cmdArgs.push("-map", `0:${s.index}`);
        if (toSrtCodecs.includes(c) || toSrtCodecIDs.includes(cid)) {
          cmdArgs.push(`-c:s:${idx}`, "srt");
        } else {
          cmdArgs.push(`-c:s:${idx}`, "copy");
        }
      });
    } else {
      cmdArgs.push("-sn");
    }
  };

  // 8. Assemble Single-Pass FFmpeg Execution Command
  const extractFfmpegError = (stderrStr) => {
    const lines = String(stderrStr || "")
      .split("\n")
      .map(l => l.trim())
      .filter(l => l && !l.startsWith("configuration:") && !l.startsWith("lib") && !l.startsWith("ffmpeg version"));
    const specific = lines.filter(l => /error|failed|unsupported|invalid|cannot|only one of them|ratecontrol|qsv|vaapi/i.test(l));
    const chosen = specific.length > 0 ? specific.slice(-3) : lines.slice(-3);
    return chosen.join(" | ").substring(0, 240);
  };

  const runFfmpeg = (useHybrid = false, forceStreamCopy = false, useIcqOnly = false) => {
    const cmdArgs = ["-y", "-fflags", "+genpts+igndts"];
    const doCopyVideo = isAlreadyAV1 || forceStreamCopy;

    if (!doCopyVideo) {
      // Both Full Hardware and Hybrid modes require VAAPI->QSV device context for av1_qsv encoder
      cmdArgs.push(
        "-init_hw_device", `vaapi=va:${gpuDevice}`,
        "-init_hw_device", "qsv=hw@va",
        "-filter_hw_device", "hw"
      );
      if (!useHybrid) {
        // Full Hardware QSV Decode
        cmdArgs.push(
          "-hwaccel", "qsv",
          "-hwaccel_device", "hw",
          "-hwaccel_output_format", "qsv",
          "-extra_hw_frames", "64"
        );
      }
    }

    cmdArgs.push("-i", inputPath);

    if (hasClampedChapters && clampedMetaPath) {
      cmdArgs.push("-i", clampedMetaPath, "-map_metadata", "0", "-map_chapters", "1");
    }

    // Video Mapping & Encoding / Stream-Copy Arguments
    cmdArgs.push("-map", `0:${mainVideo.index}`);
    if (doCopyVideo) {
      cmdArgs.push("-c:v", "copy");
    } else {
      if (useHybrid) {
        cmdArgs.push("-vf", "format=p010le");
      } else if (is10Bit) {
        cmdArgs.push("-vf", "vpp_qsv");
      } else {
        cmdArgs.push("-vf", "vpp_qsv=format=p010");
      }

      if (isHdr) {
        if (isHlg) {
          cmdArgs.push("-color_primaries", "bt2020", "-color_trc", "arib-std-b67", "-colorspace", "bt2020nc");
        } else {
          cmdArgs.push("-color_primaries", "bt2020", "-color_trc", "smpte2084", "-colorspace", "bt2020nc");
        }
      }

      cmdArgs.push(
        "-c:v", "av1_qsv",
        "-preset", "slow",
        "-global_quality", `${quality}`,
        "-extbrc", "1",
        "-look_ahead", "1",
        "-look_ahead_depth", "40",
        "-adaptive_i", "1",
        "-adaptive_b", "1",
        "-b_strategy", "1",
        "-g", "120"
      );
    }

    // Stamp flow signature on all encoded and bloat-fallback files to prevent re-encode loops
    if (!doCopyVideo || forceStreamCopy) {
      cmdArgs.push("-metadata:g", "encoded_by=ArcAV1_QSV");
    }

    // Audio & Subtitle Mappings
    appendAudioAndSubArgs(cmdArgs);

    // Purge Junk Data/Attachments & Apply Seek-Healing Muxer Stability Flags
    cmdArgs.push(
      "-map", "-0:d?",
      "-map", "-0:t?",
      "-max_interleave_delta", "0",
      "-avoid_negative_ts", "make_zero",
      "-max_muxing_queue_size", "2048",
      outputPath
    );

    log(`[Arc AV1 Single-Pass] Executing: ${ffmpegBin} ${cmdArgs.join(" ")}`);
    return spawnSync(ffmpegBin, cmdArgs, { encoding: "utf8", maxBuffer: 50 * 1024 * 1024 });
  };

  log(`[Arc AV1 Single-Pass] Processing: ${inputPath} (Already AV1: ${isAlreadyAV1}, Quality: ${quality}, Mode: ${pipelineMode})`);
  let res = runFfmpeg(needsProactiveHybrid, false);

  // Self-Healing Hybrid Fallback: If Full Hardware QSV failed and wasn't already in Hybrid or AV1 mode, retry once in Hybrid mode (CPU Decode + GPU Encode)
  if (res.status !== 0 && !isAlreadyAV1 && !needsProactiveHybrid) {
    const errTail = extractFfmpegError(res.stderr);
    log(`[Arc AV1 Single-Pass] Full Hardware QSV failed (exit ${res.status}: ${errTail}). Retrying in Hybrid Fallback mode (CPU Decode + GPU Encode)...`);
    pipelineMode = `Hybrid (CPU Decode [${vCodec}${is10Bit ? " 10-bit" : ""}] + Arc QSV AV1 Encode) [Self-Healing Fallback]`;
    if (isHdr) pipelineMode += isHlg ? " [HLG]" : " [HDR10]";
    if (fs.existsSync(outputPath)) { try { fs.unlinkSync(outputPath); } catch (e) {} }
    res = runFfmpeg(true, false);
  }

  // Cleanup temporary clamped chapters file if created
  const cleanupChapters = () => {
    if (clampedMetaPath && fs.existsSync(clampedMetaPath)) {
      try { fs.unlinkSync(clampedMetaPath); } catch (_) {}
    }
  };

  if (res.status !== 0 || !fs.existsSync(outputPath)) {
    cleanupChapters();
    const errTail = extractFfmpegError(res.stderr);
    const errReason = errTail
      ? `FFmpeg exit ${res.status}: ${errTail}`
      : `FFmpeg process exited with status ${res.status}`;
    log(`[Arc AV1 Single-Pass] Transcode execution failed critically: ${errReason}`);
    const totalDurationStr = formatDuration(Date.now() - startEpoch);
    const failPayload = {
      embeds: [{
        title: `❌ ${titleName}`,
        description: [
          `⚠️ **Error:** \`${errReason.replace(/`/g, "'")}\``,
          `⏱️ **Duration:** ${totalDurationStr}`
        ].join("\n"),
        color: 15158332,
        footer: { text: "Tdarr AV1 Flow • Transcode Failure Alert" },
        timestamp: new Date().toISOString()
      }]
    };
    await sendWebhookWithRetry(webhookUrl, failPayload, "Discord Failure Notifier", 3);
    return { outputFileObj: args.inputFileObj, outputNumber: 2, variables: args.variables };
  }

  // 9. 7-Tier Dual-Condition Dynamic Size & Quality Guard
  const outputStat = fs.statSync(outputPath);
  const newSizeMB = outputStat.size / (1024 * 1024);
  const origGB = rawSizeMB > 0 ? (rawSizeMB / 1024) : 0;
  const ratioPct = rawSizeMB > 0 ? ((newSizeMB / rawSizeMB) * 100) : 100;

  const is4K = width >= 3840 || height >= 1600;
  const is1080p = (width >= 1920 || height >= 1000) && !is4K;

  let tierName = "Tier 7: 720p / SD / Low-Res";
  let minRatioPct = 6.0;
  let maxRatioPct = 115.0;
  let minAbsoluteMB = 25;

  if (is4K) {
    if (origGB >= 40) {
      tierName = "Tier 1: Massive 4K UHD Remux (>= 40 GB)";
      minRatioPct = 1.5; maxRatioPct = 85.0; minAbsoluteMB = 300;
    } else if (origGB >= 15) {
      tierName = "Tier 2: Standard 4K Web/Rip (15 - 40 GB)";
      minRatioPct = 3.0; maxRatioPct = 95.0; minAbsoluteMB = 250;
    } else {
      tierName = "Tier 3: Light 4K Web-DL (< 15 GB)";
      minRatioPct = 4.0; maxRatioPct = 105.0; minAbsoluteMB = 200;
    }
  } else if (is1080p) {
    if (origGB >= 20) {
      tierName = "Tier 4: Heavy 1080p Remux (>= 20 GB)";
      minRatioPct = 2.5; maxRatioPct = 90.0; minAbsoluteMB = 150;
    } else if (origGB >= 5) {
      tierName = "Tier 5: Standard 1080p Blu-ray/Web (5 - 20 GB)";
      minRatioPct = 4.0; maxRatioPct = 105.0; minAbsoluteMB = 100;
    } else {
      tierName = "Tier 6: Compressed 1080p (< 5 GB)";
      minRatioPct = 5.0; maxRatioPct = 110.0; minAbsoluteMB = 50;
    }
  }

  // Require at least 15% size reduction when re-encoding an already-AV1 file
  if (isOversizedAV1) {
    maxRatioPct = Math.min(maxRatioPct, 85.0);
    tierName += " • Oversized AV1 Re-Encode (<=85% Target)";
  }

  // Dual-Condition Corrupt Protection (or < 1% on remux)
  const isUndersized = isAlreadyAV1
    ? (ratioPct < 1.0 || newSizeMB < 0.1)
    : ((ratioPct < minRatioPct) && (newSizeMB < minAbsoluteMB));
  const isBloat = !isAlreadyAV1 && (ratioPct > maxRatioPct);

  if (isUndersized) {
    cleanupChapters();
    console.log(`[Size Guard] Output file undersized: ${newSizeMB.toFixed(2)} MB (${ratioPct.toFixed(1)}%). Deleting corrupt cache.`);
    try { fs.unlinkSync(outputPath); } catch (e) {}
    const totalDurationStr = formatDuration(Date.now() - startEpoch);
    const underPayload = {
      embeds: [{
        title: `🗑️ ${titleName}`,
        description: [
          `📁 **Cache Size:** \`${formatSize(newSizeMB)}\` *(Source was ${formatSize(rawSizeMB)})*`,
          `🛡️ **Floor:** < ${minRatioPct}% or < ${minAbsoluteMB} MB`,
          `⏱️ **Duration:** ${totalDurationStr}`
        ].join("\n"),
        color: 15158332,
        footer: { text: "Tdarr AV1 Flow • Corrupt File Guard" },
        timestamp: new Date().toISOString()
      }]
    };
    await sendWebhookWithRetry(webhookUrl, underPayload, "Discord Undersized", 3);
    return { outputFileObj: args.inputFileObj, outputNumber: 2, variables: args.variables };
  }

  // Bloat Protection (> maxRatioPct for tier)
  if (isBloat) {
    console.log(`[Size Guard] Size bloat detected: ${ratioPct.toFixed(1)}% > ${maxRatioPct}% (${tierName}). Discarding transcode cache and falling back to stream-copy remux.`);
    const bloatedMB = newSizeMB;
    const bloatDiffMB = bloatedMB - rawSizeMB;
    const bloatDiffPct = ratioPct - 100;
    const bloatDiffPctStr = `${bloatDiffPct >= 0 ? "+" : ""}${bloatDiffPct.toFixed(1)}%`;
    try { fs.unlinkSync(outputPath); } catch (e) {}

    // Remux original video stream with full audio/subtitle normalization & seek healing
    const remuxRes = runFfmpeg(false, true);
    cleanupChapters();

    if (remuxRes.status !== 0 || !fs.existsSync(outputPath)) {
      return { outputFileObj: args.inputFileObj, outputNumber: 2, variables: args.variables };
    }

    pipelineMode = "Size Bloat Fallback (Original Video Stream-Copy + Seek Healed)";
    const totalDurationStr = formatDuration(Date.now() - startEpoch);
    const bloatPayload = {
      embeds: [{
        title: `⚠️ ${titleName}`,
        description: [
          `📁 **Size Impact:** \`${formatSize(rawSizeMB)}\` ➔ \`${formatSize(bloatedMB)}\` **(${bloatDiffPctStr} • ${formatSize(Math.abs(bloatDiffMB))} bloat)**`,
          `🛡️ **Guard:** ${tierName} (Max ${maxRatioPct}% limit)`,
          `⏱️ **Duration:** ${totalDurationStr}`
        ].join("\n"),
        color: 15844367,
        footer: { text: "Tdarr AV1 Flow • Dynamic Size Ratio Guard" },
        timestamp: new Date().toISOString()
      }]
    };
    await sendWebhookWithRetry(webhookUrl, bloatPayload, "Discord Bloat Notifier", 3);
  } else {
    cleanupChapters();
  }

  // 10. Persist Pipeline Metadata for Post-Replace *ARR Rescan & Discord Success Notification
  // Validate the final output, including stream-copy fallbacks, before replacing anything.
  try {
    const expectedCodec = (isAlreadyAV1 || isBloat) ? vCodec : "av1";
    const result = validateOutput(ffprobeBin, inputPath, outputPath, {
      audio: finalAudioStreams.length, subtitle: finalSubStreams.length, codec: expectedCodec,
      audioCodecs: finalAudioStreams.map(s => (parseInt(s.channels || 0, 10) > 2 && ((s.codec_name || "").toLowerCase() !== "eac3" || parseInt(s.channels || 0, 10) > 6)) ? "eac3" : s.codec_name),
      subtitleCodecs: finalSubStreams.map(s => (toSrtCodecs.includes((s.codec_name || "").toLowerCase()) || toSrtCodecIDs.includes((s.codec_tag_string || s.codec_id || "").toLowerCase())) ? "subrip" : s.codec_name)
    });
    log(`[Output validation] Duration ${result.sourceDuration}s -> ${result.outputDuration}s; expected streams and codec found.`);
    const originalPath = args.originalLibraryFile?._id;
    if (!originalPath || !fs.existsSync(originalPath)) throw new Error("Original library file is not accessible from this node");
    const destinationPath = path.join(path.dirname(originalPath), path.basename(outputPath));
    if (destinationPath !== originalPath && fs.existsSync(destinationPath)) throw new Error(`Replacement destination already exists: ${destinationPath}`);
  } catch (err) {
    log(`[Safety check failed] ${err.message || err}. Original will not be replaced.`);
    return { outputFileObj: args.inputFileObj, outputNumber: 2, variables: args.variables };
  }

  const finalStat = fs.statSync(outputPath);
  const finalMB = finalStat.size / (1024 * 1024);

  const newTotalKbps = durationSec > 0 ? Math.round((finalMB * 1024 * 1024 * 8) / (durationSec * 1000)) : 0;
  let newAudioKbps = 0;
  finalAudioStreams.forEach(s => {
    const ch = parseInt(s.channels || 0, 10);
    const c = (s.codec_name || "").toLowerCase();
    const isTranscodedToEac3 = ch > 2 && (c !== "eac3" || ch > 6);
    if (isTranscodedToEac3) {
      newAudioKbps += 640;
    } else {
      newAudioKbps += Math.round(parseInt(s.bit_rate || s.tags?.BPS || (ch > 2 ? 640 : 192), 10) / 1000);
    }
  });
  const newVideoKbps = (isAlreadyAV1 || isBloat) ? estVideoBitrateKbps : Math.max(0, newTotalKbps - newAudioKbps);

  const isTargetRam = typeof targetDir === "string" && targetDir.startsWith("/dev/shm");
  args.variables.user.transcode_medium = isTargetRam ? "RAM" : "Disk";
  args.variables.user.qsv_mode = pipelineMode;
  args.variables.user.is_bloat_fallback = isBloat;
  args.variables.user.final_size_mb = finalMB;
  args.variables.user.orig_video_kbps = estVideoBitrateKbps;
  args.variables.user.new_video_kbps = newVideoKbps;
  args.variables.user.quality_value = quality;
  if (!isAlreadyAV1 && !isBloat) {
    args.variables.user.transcode_start_ts = startEpoch;
    args.variables.user.transcode_end_ts = Date.now();
  } else {
    delete args.variables.user.transcode_start_ts;
    delete args.variables.user.transcode_end_ts;
  }

  // Return updated output file object pointing to cache output
  const outputObj = buildOutputObj(args.inputFileObj, outputPath, cleanBase);
  return {
    outputFileObj: outputObj,
    outputNumber: 1,
    variables: args.variables
  };
};

module.exports = async (args) => {
  const http = require("http");
  const https = require("https");
  const path = require("path");

  const log = (msg) => {
    console.log(msg);
    if (typeof args.jobLog === "function") {
      try { args.jobLog(msg); } catch (_) {}
    }
  };

  const ARR_CONFIG = {
    radarr: {
      label: "Radarr Movies (:7878)",
      type: "radarr",
      host: "http://192.168.50.217:7878",
      apiKey: "bfa9ebb0a99443f4b01eadbb9339cb7a"
    },
    sonarrTv: {
      label: "Sonarr TV (:8989)",
      type: "sonarr",
      host: "http://192.168.50.217:8989",
      apiKey: "6a6b8ecd60a84ec197645cc3a4f8a0a4"
    },
    sonarrAnime: {
      label: "Sonarr Anime (:8990)",
      type: "sonarr",
      host: "http://192.168.50.217:8990",
      apiKey: "ddd2690ffb6c41049516a6402436fe94"
    }
  };

  const filePath = (args.inputFileObj?._id || args.originalLibraryFile?._id || "").replace(/\\/g, "/");
  if (!filePath) {
    return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
  }

  const parts = filePath.split("/").filter(Boolean);
  const lowerParts = parts.map(p => p.toLowerCase());

  let target = null;
  let contentFolder = "";

  const animeIdx = lowerParts.indexOf("anime");
  const tvIdx = lowerParts.findIndex(p => p === "tv" || p === "shows" || p === "series");
  const movieIdx = lowerParts.findIndex(p => p === "movies" || p === "movie" || p === "films");

  if (animeIdx !== -1) {
    target = ARR_CONFIG.sonarrAnime;
    contentFolder = parts[animeIdx + 1] || "";
  } else if (tvIdx !== -1) {
    target = ARR_CONFIG.sonarrTv;
    contentFolder = parts[tvIdx + 1] || "";
  } else if (movieIdx !== -1) {
    target = ARR_CONFIG.radarr;
    contentFolder = parts[movieIdx + 1] || "";
  }

  if (!target || !target.host || !target.apiKey) {
    log(`[ARR Notifier] File path '${filePath}' did not match /movies/, /tv/, or /anime/ — skipping rescan.`);
    return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
  }

  const arrRequest = (method, urlStr, apiKey, bodyObj = null) => {
    return new Promise((resolve) => {
      let url;
      try {
        url = new URL(urlStr);
      } catch (e) {
        return resolve({ ok: false, statusCode: 0, error: e });
      }
      const lib = url.protocol === "https:" ? https : http;
      const postData = bodyObj ? JSON.stringify(bodyObj) : null;
      const headers = {
        "X-Api-Key": apiKey,
        "Accept": "application/json",
        "User-Agent": "Tdarr-ArrNotifier/1.0"
      };
      if (postData) {
        headers["Content-Type"] = "application/json";
        headers["Content-Length"] = Buffer.byteLength(postData);
      }

      const req = lib.request({
        hostname: url.hostname,
        port: url.port || (url.protocol === "https:" ? 443 : 80),
        path: url.pathname + url.search,
        method: method,
        headers: headers
      }, (res) => {
        let raw = "";
        res.on("data", chunk => { raw += chunk; });
        res.on("end", () => {
          let parsed = null;
          try { if (raw) parsed = JSON.parse(raw); } catch (_) {}
          resolve({
            ok: res.statusCode >= 200 && res.statusCode < 300,
            statusCode: res.statusCode,
            data: parsed
          });
        });
      });

      req.on("error", (err) => {
        resolve({ ok: false, statusCode: 0, error: err });
      });

      req.setTimeout(10000, () => {
        req.destroy();
        resolve({ ok: false, statusCode: 0, timeout: true });
      });

      if (postData) req.write(postData);
      req.end();
    });
  };

  try {
    const baseUrl = target.host.replace(/\/+$/, "");
    const isSonarr = target.type === "sonarr";
    const listEndpoint = `${baseUrl}/api/v3/${isSonarr ? "series" : "movie"}`;
    const listRes = await arrRequest("GET", listEndpoint, target.apiKey);

    let matchedItem = null;
    if (listRes.ok && Array.isArray(listRes.data)) {
      // Tier 1: Exact path prefix match
      matchedItem = listRes.data.find(item => {
        if (!item.path) return false;
        const p = item.path.replace(/\\/g, "/").replace(/\/+$/, "");
        return filePath === p || filePath.startsWith(p + "/");
      });

      // Tier 2: Content folder basename match (Docker volume mount agnostic)
      if (!matchedItem && contentFolder) {
        const cleanFolderLower = contentFolder.toLowerCase();
        matchedItem = listRes.data.find(item => {
          if (!item.path) return false;
          const p = item.path.replace(/\\/g, "/").replace(/\/+$/, "");
          const base = p.split("/").pop() || "";
          return base.toLowerCase() === cleanFolderLower;
        });
      }
    }

    // Tier 3: Fallback to /api/v3/parse if folder lookup did not match
    let targetId = matchedItem?.id || null;
    let matchedTitle = matchedItem?.title || contentFolder || path.posix.basename(filePath);

    if (!targetId) {
      const fileName = path.posix.basename(filePath);
      const parseUrl = `${baseUrl}/api/v3/parse?title=${encodeURIComponent(fileName)}`;
      const parseRes = await arrRequest("GET", parseUrl, target.apiKey);
      if (parseRes.ok && parseRes.data) {
        if (isSonarr && parseRes.data.series?.id) {
          targetId = parseRes.data.series.id;
          matchedTitle = parseRes.data.series.title || matchedTitle;
        } else if (!isSonarr && (parseRes.data.movie?.id || parseRes.data.movie?.movieFile?.movieId)) {
          targetId = parseRes.data.movie?.id || parseRes.data.movie?.movieFile?.movieId;
          matchedTitle = parseRes.data.movie?.title || matchedTitle;
        }
      }
    }

    if (targetId) {
      const cmdName = isSonarr ? "RescanSeries" : "RescanMovie";
      const cmdBody = isSonarr
        ? { name: "RescanSeries", seriesId: targetId }
        : { name: "RescanMovie", movieId: targetId };
      const cmdRes = await arrRequest("POST", `${baseUrl}/api/v3/command`, target.apiKey, cmdBody);
      if (cmdRes.ok) {
        log(`[ARR Notifier] Triggered ${cmdName} for '${matchedTitle}' (ID: ${targetId}) on ${target.label} (HTTP ${cmdRes.statusCode})`);
      } else {
        log(`[ARR Notifier] Warning: ${cmdName} command on ${target.label} returned HTTP ${cmdRes.statusCode}`);
      }
    } else {
      log(`[ARR Notifier] Could not resolve ${isSonarr ? "seriesId" : "movieId"} for '${contentFolder || filePath}' on ${target.label}`);
    }
  } catch (err) {
    log(`[ARR Notifier] Non-fatal error communicating with ${target.label}: ${err.message || err}`);
  }

  return {
    outputFileObj: args.inputFileObj,
    outputNumber: 1,
    variables: args.variables
  };
};

module.exports = async (args) => {
  const https = require("https");
  const webhookUrl = process.env.TDARR_DISCORD_WEBHOOK || "";

  const formatSize = (mb) => {
    if (mb === undefined || mb === null || isNaN(mb) || mb <= 0) return "0 MB";
    const abs = Math.abs(mb);
    if (abs >= 1024) return (abs / 1024).toFixed(2) + " GB";
    return abs.toFixed(1) + " MB";
  };

  const formatBitrate = (kbps) => {
    if (!kbps || isNaN(kbps) || kbps <= 0) return "0 kbps";
    const k = Math.round(kbps);
    if (k >= 1000) return (k / 1000).toFixed(2) + " Mbps";
    return `${k} kbps`;
  };

  const formatDuration = (ms) => {
    if (!ms || ms < 0) return "0s";
    const totalSec = Math.max(1, Math.round(ms / 1000));
    const h = Math.floor(totalSec / 3600);
    const m = Math.floor((totalSec % 3600) / 60);
    const s = totalSec % 60;
    if (h > 0) return `${h}h ${m}m ${s}s`;
    if (m > 0) return `${m}m ${s}s`;
    return `${s}s`;
  };

  const cleanFolder = (fullPath) => {
    if (!fullPath || fullPath === "Unknown file") return "Unknown folder";
    const parts = fullPath.split("/").filter(p => p && p !== "mnt" && p !== "media");
    if (parts.length <= 1) return "Root";
    parts.pop();
    const take = Math.min(parts.length, 3);
    return parts.slice(-take).join(" / ");
  };

  const formatPipelineMode = (rawMode) => {
    if (!rawMode) return "Intel Arc GPU (Full Hardware)";
    const mode = rawMode.trim();
    if (mode.includes("Full QSV Hardware")) {
      if (mode.includes("HDR10")) return "Intel Arc GPU • HDR10";
      if (mode.includes("HLG")) return "Intel Arc GPU • HLG";
      return "Intel Arc GPU (Full Hardware)";
    }
    if (mode.includes("Hybrid")) {
      if (mode.includes("Fallback")) return "Hybrid Fallback (CPU Decode + GPU Encode)";
      if (mode.includes("CPU Decode")) return "Hybrid (CPU Decode + GPU Encode)";
      if (mode.includes("Downsample")) return "Hybrid (Color Conversion + GPU Encode)";
      return "Hybrid (CPU + GPU)";
    }
    if (mode.includes("Subtitle Normalization") || mode.includes("Seek Healing") || mode.includes("Compliant") || mode.includes("Remux")) {
      return "Fast Remux (Subtitles & Seek Repair)";
    }
    if (mode.includes("Bloat")) {
      return "Original Preserved (Bloat Protected)";
    }
    return mode;
  };

  const startEpoch = args.variables?.user?.workflow_start_epoch;
  const totalWallMs = startEpoch ? Math.max(0, Date.now() - startEpoch) : 0;
  const totalDurationStr = formatDuration(totalWallMs);

  const transcodeStartTs = args.variables?.user?.transcode_start_ts;
  const transcodeEndTs = args.variables?.user?.transcode_end_ts;

  const badImageCodecs = ["mjpeg", "bmp", "png", "gif", "tiff", "otf", "ttf"];
  const vStream = (args.originalLibraryFile?.ffProbeData?.streams || []).find(s => {
    if (s.codec_type !== "video") return false;
    const c = (s.codec_name || "").toLowerCase();
    const isPic = s.disposition?.attached_pic === 1 || s.disposition?.timed_thumbnails === 1;
    return !badImageCodecs.includes(c) && !isPic;
  });
  const totalFrames = parseInt(vStream?.tags?.NUMBER_OF_FRAMES || vStream?.tags?.["NUMBER_OF_FRAMES-eng"] || vStream?.nb_frames || 0, 10);

  const filePath = args.originalLibraryFile?._id || args.inputFileObj?._id || "Unknown file";
  const fileName = filePath.split("/").pop();
  const titleName = (args.originalLibraryFile?.fileNameWithoutExtension || fileName.replace(/\.[^/.]+$/, "") || fileName)
    .replace(/(_(salvaged|healed|eac3|temp|singlepass)|-TdarrCacheFile-[A-Za-z0-9_-]+)$/g, "");
  const folderDisplay = cleanFolder(filePath);

  const origMB = args.originalLibraryFile?.file_size || 0;
  const newMB = args.inputFileObj?.file_size || args.variables?.user?.final_size_mb || 0;

  const isFallback = args.variables?.user?.is_bloat_fallback === true;
  let pipelineMode = args.variables?.user?.qsv_mode;
  if (!pipelineMode) {
    if (isFallback) {
      pipelineMode = "Size Bloat Fallback (Original Video Stream-Copy + Seek Healed)";
    } else if (transcodeStartTs && transcodeEndTs) {
      pipelineMode = "Full QSV Hardware";
    } else {
      pipelineMode = "Library Reprocessing: Subtitle Normalization & Seek Healing";
    }
  }

  let statusStr = "Transcode Complete (AV1)";
  if (transcodeStartTs && transcodeEndTs) {
    statusStr = "Transcode Complete (AV1)";
  } else if (isFallback) {
    statusStr = "Stream Healed & Remuxed *(Size Bloat Fallback)*";
  } else {
    statusStr = "Compliant • AV1 Remux Healed";
  }

  let sizeStr = "";
  if (origMB > 0 && newMB > 0) {
    const ratio = ((newMB / origMB) * 100).toFixed(1);
    const diffMB = origMB - newMB;
    if (diffMB > 0.05) {
      const pctSaved = (100 - ratio).toFixed(1);
      sizeStr = `\`${formatSize(origMB)}\` ➔ \`${formatSize(newMB)}\` **(-${pctSaved}% • ${formatSize(diffMB)} saved)**`;
    } else if (diffMB < -0.05) {
      const pctAdded = (ratio - 100).toFixed(1);
      sizeStr = `\`${formatSize(origMB)}\` ➔ \`${formatSize(newMB)}\` **(+${pctAdded}% • Tracks normalized)**`;
    } else {
      sizeStr = `\`${formatSize(origMB)}\` **(Preserved)**`;
    }
  } else {
    sizeStr = `\`${formatSize(newMB || origMB)}\``;
  }

  const origVidKbps = args.variables?.user?.orig_video_kbps || (() => {
    const durSec = parseFloat(args.originalLibraryFile?.ffProbeData?.format?.duration || args.originalLibraryFile?.meta?.Duration || 0);
    if (durSec <= 0 || !origMB) return 0;
    const totKbps = Math.round((origMB * 1024 * 1024 * 8) / (durSec * 1000));
    let nonVid = 0;
    (args.originalLibraryFile?.ffProbeData?.streams || []).forEach(s => {
      if (s.codec_type === "audio") {
        const br = parseInt(s.bit_rate || s.tags?.BPS || 0, 10);
        nonVid += br > 0 ? Math.round(br / 1000) : (parseInt(s.channels || 2, 10) > 2 ? 640 : 192);
      }
    });
    return Math.max(0, totKbps - nonVid);
  })();

  const newVidKbps = args.variables?.user?.new_video_kbps || (() => {
    const durSec = parseFloat(args.originalLibraryFile?.ffProbeData?.format?.duration || args.originalLibraryFile?.meta?.Duration || 0);
    if (durSec <= 0 || !newMB) return 0;
    const totKbps = Math.round((newMB * 1024 * 1024 * 8) / (durSec * 1000));
    let nonVid = 0;
    (args.originalLibraryFile?.ffProbeData?.streams || []).forEach(s => {
      if (s.codec_type === "audio") {
        const ch = parseInt(s.channels || 2, 10);
        const c = (s.codec_name || "").toLowerCase();
        if (ch > 2 && (c !== "eac3" || ch > 6)) {
          nonVid += 640;
        } else {
          const br = parseInt(s.bit_rate || s.tags?.BPS || 0, 10);
          nonVid += br > 0 ? Math.round(br / 1000) : (ch > 2 ? 640 : 192);
        }
      }
    });
    return Math.max(0, totKbps - nonVid);
  })();

  const qualVal = args.variables?.user?.quality_value;
  let bitrateStr = "";
  if (transcodeStartTs && transcodeEndTs && origVidKbps > 0 && newVidKbps > 0) {
    const brRatio = ((newVidKbps / origVidKbps) * 100).toFixed(1);
    const brDiff = origVidKbps - newVidKbps;
    let brPctStr = "";
    if (brDiff > 0) {
      const brPctSaved = (100 - brRatio).toFixed(1);
      brPctStr = `-${brPctSaved}%`;
    } else if (brDiff < 0) {
      const brPctAdded = (brRatio - 100).toFixed(1);
      brPctStr = `+${brPctAdded}%`;
    } else {
      brPctStr = "0.0%";
    }
    const qualDesc = qualVal ? `QSV quality ${qualVal}` : "QSV quality mode";
    bitrateStr = `\`${formatBitrate(origVidKbps)}\` ➔ \`${formatBitrate(newVidKbps)}\` **(${brPctStr} • ${qualDesc})**`;
  } else if (isFallback) {
    bitrateStr = `\`${formatBitrate(origVidKbps || newVidKbps)}\` **(Original Video Preserved • Bloat Protected)**`;
  } else if (origVidKbps > 0 || newVidKbps > 0) {
    bitrateStr = `\`${formatBitrate(newVidKbps || origVidKbps)}\` **(Stream-Copy Preserved)**`;
  }

  const medium = args.variables?.user?.transcode_medium || ((args.inputFileObj?._id || "").startsWith("/dev/shm") ? "RAM" : "Disk");
  const mediumTag = medium === "RAM" ? "🧠 RAM" : "💽 Disk";

  const descLines = [
    `📁 **Size:** ${sizeStr}`,
    `📊 **Bitrate:** ${bitrateStr || "\`Preserved\`"}`,
    `⚡ **Pipeline:** ${formatPipelineMode(pipelineMode)} • ${mediumTag}`,
    `⏱️ **Duration:** ${totalDurationStr}`
  ];

  const payload = JSON.stringify({
    embeds: [{
      title: `✅ ${titleName}`,
      description: descLines.join("\n"),
      color: 3066993,
      footer: {
        text: isFallback ? "Tdarr AV1 Flow • Size Bloat Fallback Success" : (statusStr.includes("Compliant") ? "Tdarr AV1 Flow • Verified Compliant" : "Tdarr AV1 Flow • Transcode Success")
      },
      timestamp: new Date().toISOString()
    }]
  });

  const sendWebhookWithRetry = async (urlStr, payloadData, tag = "Discord Notifier", maxRetries = 3) => {
    const url = new URL(urlStr);
    const postData = typeof payloadData === "string" ? payloadData : JSON.stringify(payloadData);

    for (let attempt = 1; attempt <= maxRetries; attempt++) {
      const result = await new Promise((resolve) => {
        const req = https.request({
          hostname: url.hostname,
          path: url.pathname + url.search,
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "User-Agent": "Tdarr-DiscordNotifier/1.0",
            "Content-Length": Buffer.byteLength(postData)
          }
        }, (res) => {
          let body = "";
          res.on("data", chunk => { body += chunk; });
          res.on("end", () => {
            if (res.statusCode >= 200 && res.statusCode < 300) {
              console.log(`[${tag}] Sent successfully on attempt ${attempt} (HTTP ${res.statusCode})`);
              resolve({ ok: true, statusCode: res.statusCode });
            } else if (res.statusCode === 429) {
              let retryAfter = 2000;
              try {
                const parsed = JSON.parse(body);
                if (parsed.retry_after) retryAfter = Math.ceil(parsed.retry_after * 1000);
              } catch (_) {}
              console.warn(`[${tag}] Rate limited (HTTP 429) on attempt ${attempt}. Waiting ${retryAfter}ms`);
              resolve({ ok: false, retry: true, delay: retryAfter, statusCode: 429 });
            } else if (res.statusCode >= 500) {
              console.warn(`[${tag}] Discord gateway error (HTTP ${res.statusCode}) on attempt ${attempt}`);
              resolve({ ok: false, retry: true, delay: attempt * 2000, statusCode: res.statusCode });
            } else {
              console.error(`[${tag} Fatal Error] HTTP ${res.statusCode}: ${body}`);
              resolve({ ok: false, retry: false, statusCode: res.statusCode });
            }
          });
        });

        req.on("error", (err) => {
          console.warn(`[${tag}] Network error on attempt ${attempt}: ${err.message || err}`);
          resolve({ ok: false, retry: true, delay: attempt * 2000, error: err });
        });

        req.setTimeout(15000, () => {
          console.warn(`[${tag}] Socket timeout (15s) on attempt ${attempt}`);
          req.destroy();
          resolve({ ok: false, retry: true, delay: attempt * 2000, timeout: true });
        });

        req.write(postData);
        req.end();
      });

      if (result.ok || !result.retry || attempt === maxRetries) {
        if (!result.ok && attempt === maxRetries) {
          console.error(`[${tag}] Failed to deliver notification after ${maxRetries} attempts.`);
        }
        break;
      }

      const waitMs = result.delay || (attempt * 2000);
      await new Promise(r => setTimeout(r, waitMs));
    }
  };

  try {
    await sendWebhookWithRetry(webhookUrl, payload, "Discord Success Notifier", 3);
  } catch (e) {
    console.error("[Discord Success Notifier] Exception:", e);
  }

  return {
    outputFileObj: args.inputFileObj,
    outputNumber: 1,
    variables: args.variables
  };
};

module.exports = async (args) => {
  const http = require("http");
  const https = require("https");
  const path = require("path");

  const log = (msg) => {
    console.log(msg);
    if (typeof args.jobLog === "function") {
      try { args.jobLog(msg); } catch (_) {}
    }
  };

  const ARR_CONFIG = {
    radarr: {
      label: "Radarr Movies (:7878)",
      type: "radarr",
      host: "http://192.168.50.217:7878",
      apiKey: "bfa9ebb0a99443f4b01eadbb9339cb7a"
    },
    sonarrTv: {
      label: "Sonarr TV (:8989)",
      type: "sonarr",
      host: "http://192.168.50.217:8989",
      apiKey: "6a6b8ecd60a84ec197645cc3a4f8a0a4"
    },
    sonarrAnime: {
      label: "Sonarr Anime (:8990)",
      type: "sonarr",
      host: "http://192.168.50.217:8990",
      apiKey: "ddd2690ffb6c41049516a6402436fe94"
    }
  };

  const filePath = (args.inputFileObj?._id || args.originalLibraryFile?._id || "").replace(/\\/g, "/");
  if (!filePath) {
    return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
  }

  const parts = filePath.split("/").filter(Boolean);
  const lowerParts = parts.map(p => p.toLowerCase());

  let target = null;
  let contentFolder = "";

  const animeIdx = lowerParts.indexOf("anime");
  const tvIdx = lowerParts.findIndex(p => p === "tv" || p === "shows" || p === "series");
  const movieIdx = lowerParts.findIndex(p => p === "movies" || p === "movie" || p === "films");

  if (animeIdx !== -1) {
    target = ARR_CONFIG.sonarrAnime;
    contentFolder = parts[animeIdx + 1] || "";
  } else if (tvIdx !== -1) {
    target = ARR_CONFIG.sonarrTv;
    contentFolder = parts[tvIdx + 1] || "";
  } else if (movieIdx !== -1) {
    target = ARR_CONFIG.radarr;
    contentFolder = parts[movieIdx + 1] || "";
  }

  if (!target || !target.host || !target.apiKey) {
    log(`[ARR Notifier] File path '${filePath}' did not match /movies/, /tv/, or /anime/ — skipping rescan.`);
    return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
  }

  const arrRequest = (method, urlStr, apiKey, bodyObj = null) => {
    return new Promise((resolve) => {
      let url;
      try {
        url = new URL(urlStr);
      } catch (e) {
        return resolve({ ok: false, statusCode: 0, error: e });
      }
      const lib = url.protocol === "https:" ? https : http;
      const postData = bodyObj ? JSON.stringify(bodyObj) : null;
      const headers = {
        "X-Api-Key": apiKey,
        "Accept": "application/json",
        "User-Agent": "Tdarr-ArrNotifier/1.0"
      };
      if (postData) {
        headers["Content-Type"] = "application/json";
        headers["Content-Length"] = Buffer.byteLength(postData);
      }

      const req = lib.request({
        hostname: url.hostname,
        port: url.port || (url.protocol === "https:" ? 443 : 80),
        path: url.pathname + url.search,
        method: method,
        headers: headers
      }, (res) => {
        let raw = "";
        res.on("data", chunk => { raw += chunk; });
        res.on("end", () => {
          let parsed = null;
          try { if (raw) parsed = JSON.parse(raw); } catch (_) {}
          resolve({
            ok: res.statusCode >= 200 && res.statusCode < 300,
            statusCode: res.statusCode,
            data: parsed
          });
        });
      });

      req.on("error", (err) => {
        resolve({ ok: false, statusCode: 0, error: err });
      });

      req.setTimeout(10000, () => {
        req.destroy();
        resolve({ ok: false, statusCode: 0, timeout: true });
      });

      if (postData) req.write(postData);
      req.end();
    });
  };

  try {
    const baseUrl = target.host.replace(/\/+$/, "");
    const isSonarr = target.type === "sonarr";
    const listEndpoint = `${baseUrl}/api/v3/${isSonarr ? "series" : "movie"}`;
    const listRes = await arrRequest("GET", listEndpoint, target.apiKey);

    let matchedItem = null;
    if (listRes.ok && Array.isArray(listRes.data)) {
      // Tier 1: Exact path prefix match
      matchedItem = listRes.data.find(item => {
        if (!item.path) return false;
        const p = item.path.replace(/\\/g, "/").replace(/\/+$/, "");
        return filePath === p || filePath.startsWith(p + "/");
      });

      // Tier 2: Content folder basename match (Docker volume mount agnostic)
      if (!matchedItem && contentFolder) {
        const cleanFolderLower = contentFolder.toLowerCase();
        matchedItem = listRes.data.find(item => {
          if (!item.path) return false;
          const p = item.path.replace(/\\/g, "/").replace(/\/+$/, "");
          const base = p.split("/").pop() || "";
          return base.toLowerCase() === cleanFolderLower;
        });
      }
    }

    // Tier 3: Fallback to /api/v3/parse if folder lookup did not match
    let targetId = matchedItem?.id || null;
    let matchedTitle = matchedItem?.title || contentFolder || path.posix.basename(filePath);

    if (!targetId) {
      const fileName = path.posix.basename(filePath);
      const parseUrl = `${baseUrl}/api/v3/parse?title=${encodeURIComponent(fileName)}`;
      const parseRes = await arrRequest("GET", parseUrl, target.apiKey);
      if (parseRes.ok && parseRes.data) {
        if (isSonarr && parseRes.data.series?.id) {
          targetId = parseRes.data.series.id;
          matchedTitle = parseRes.data.series.title || matchedTitle;
        } else if (!isSonarr && (parseRes.data.movie?.id || parseRes.data.movie?.movieFile?.movieId)) {
          targetId = parseRes.data.movie?.id || parseRes.data.movie?.movieFile?.movieId;
          matchedTitle = parseRes.data.movie?.title || matchedTitle;
        }
      }
    }

    if (targetId) {
      const cmdName = isSonarr ? "RescanSeries" : "RescanMovie";
      const cmdBody = isSonarr
        ? { name: "RescanSeries", seriesId: targetId }
        : { name: "RescanMovie", movieId: targetId };
      const cmdRes = await arrRequest("POST", `${baseUrl}/api/v3/command`, target.apiKey, cmdBody);
      if (cmdRes.ok) {
        log(`[ARR Notifier] Triggered ${cmdName} for '${matchedTitle}' (ID: ${targetId}) on ${target.label} (HTTP ${cmdRes.statusCode})`);
      } else {
        log(`[ARR Notifier] Warning: ${cmdName} command on ${target.label} returned HTTP ${cmdRes.statusCode}`);
      }
    } else {
      log(`[ARR Notifier] Could not resolve ${isSonarr ? "seriesId" : "movieId"} for '${contentFolder || filePath}' on ${target.label}`);
    }
  } catch (err) {
    log(`[ARR Notifier] Non-fatal error communicating with ${target.label}: ${err.message || err}`);
  }

  return {
    outputFileObj: args.inputFileObj,
    outputNumber: 1,
    variables: args.variables
  };
};

module.exports = async (args) => {
  const fs = require("fs");
  const path = require("path");
  const tempDir = args.variables?.user?.safety_temp_dir;
  const output = args.variables?.user?.safety_temp_output;
  const log = msg => { if (typeof args.jobLog === "function") args.jobLog(msg); else console.log(msg); };
  try {
    if (typeof tempDir === "string" && path.isAbsolute(tempDir) && /^tdarr-av1-[a-zA-Z0-9]+$/.test(path.basename(tempDir))) {
      if (typeof output === "string" && path.dirname(output) === tempDir && fs.existsSync(output)) fs.unlinkSync(output);
      fs.rmdirSync(tempDir);
    }
  } catch (e) { log(`[Cache cleanup] Could not remove job cache: ${e.message || e}`); }
  if (args.variables?.user) { delete args.variables.user.safety_temp_dir; delete args.variables.user.safety_temp_output; }
  return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
};

